import React, { useEffect, useState } from 'react';
import { fetchResorts, fetchResort } from './api';

function App() {
  const [resorts, setResorts] = useState([]);
  const [selectedResort, setSelectedResort] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const getResorts = async () => {
      try {
        const data = await fetchResorts();
        setResorts(data || []);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };
    getResorts();
  }, []);

  const handleResortClick = async (name) => {
    try {
      const data = await fetchResort(name);
      setSelectedResort(data);
    } catch (err) {
      setError(err.message);
    }
  };

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;

  return (
    <div>
      <h1>Ski Resorts</h1>
      <ul>
        {resorts.length > 0 ? (
          resorts.map((resort) => (
            <li key={resort.id} onClick={() => handleResortClick(resort.name)}>
              {resort.name}
            </li>
          ))
        ) : (
          <li>No resorts available</li>
        )}
      </ul>
      {selectedResort && (
        <div>
          <h2>{selectedResort.name}</h2>
          <p>{selectedResort.description}</p>
        </div>
      )}
    </div>
  );
}

export default App;
